input.content:
workspace "Energy Manager" "A home energy management platform that helps homeowners manage their household's energy use and costs." {

    model {

        homeowner = person "Homeowner" "A homeowner who uses the platform to manage their household's energy use and costs."

        smartMeterProvider = softwareSystem "Smart Meter Provider" "An external service, operated by a different organization, that provides live meter readings." "External"

        energyManager = softwareSystem "Energy Manager" "A home energy management platform, owned and operated by our company, that helps homeowners manage their household's energy use and costs." {
            dashboard = container "Dashboard Web App" "A web app where homeowners see their household's energy consumption and costs. Embeds the shared rates library, which computes energy prices from tariff and time of day." "Web application" "Web"
            scheduling = container "Scheduling Service" "A service that plans charging and heating for the household. Embeds the shared rates library, which computes energy prices from tariff and time of day." "Service"
            database = container "Database" "Stores meter readings and schedules." "Database" "Database"
        }

        homeowner -> dashboard "views household energy consumption and costs" "HTTPS/JSON"
        scheduling -> smartMeterProvider "fetches live meter readings from" "HTTPS/JSON"
        scheduling -> database "stores meter readings and schedules in" "SQL"
        dashboard -> database "reads meter readings from" "SQL"

    }

    views {
        systemContext energyManager "SystemContext" {
            include *
            autoLayout
            title "System Context for Energy Manager"
        }
        container energyManager "Containers" {
            include *
            autoLayout
            title "Containers for Energy Manager"
        }
        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            relationship "Relationship" {
                routing Orthogonal
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}

